//! Resumable context-compilation workflow fabric for Worldgen P03 F13-F16.
use super::context_copilot_support::{self,ContextCopilotReceipt,ContextCopilotRequest};
use bioprism_foundation::{PRECLINICAL_BOUNDARY,RESEARCH_CONTRACT_SCHEMA_VERSION};
use bioprism_ids::ContentHash;
use serde::{Deserialize,Serialize};
use serde_json::json;
use std::collections::BTreeSet;
use thiserror::Error;
pub const CONTENT_TYPE:&str="application/vnd.aurora.worldgen.context-workflow-receipt+json";
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct ContextWorkflowRequest{pub workflow_id:String,pub copilot:ContextCopilotRequest,pub stage_order:Vec<String>,pub completed_stage_order:Vec<String>,pub checkpoint_seq:u64,pub budget_units:u64,pub compensation_enabled:bool,pub replay_identity:ContentHash}
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct ContextWorkflowReceipt{pub schema_version:String,pub contract_version:String,pub feature_id:String,pub workflow_id:String,pub disposition:String,pub stage_order:Vec<String>,pub completed_stage_order:Vec<String>,pub pending_stage_order:Vec<String>,pub compensation_order:Vec<String>,pub checkpoint_seq:u64,pub budget_units:u64,pub consumed_units:u64,pub replay_identity:ContentHash,pub copilot:ContextCopilotReceipt,pub workflow_digest:ContentHash,pub artifact:serde_json::Value,pub effect_receipts:Vec<String>,pub raw_data_local:bool,pub aggregate_only:bool,pub boundary:String}
#[derive(Debug,Error,Clone,PartialEq,Eq)]pub enum ContextWorkflowError{#[error("invalid context workflow request: {0}")]Invalid(String),#[error("invalid context workflow receipt: {0}")]Receipt(String),#[error("context workflow artifact failed: {0}")]Artifact(String)}
fn digest(v:&ContentHash)->bool{v.as_str().len()==64&&v.as_str().bytes().all(|b|b.is_ascii_hexdigit())}fn ordered(v:&[String])->bool{v.windows(2).all(|p|p[0]<p[1])}fn sorted(v:&[String])->Vec<String>{let mut out=v.to_vec();out.sort();out.dedup();out}
impl ContextWorkflowReceipt{pub fn validate(&self)->Result<(),ContextWorkflowError>{if self.schema_version!=RESEARCH_CONTRACT_SCHEMA_VERSION||self.contract_version.trim().is_empty()||self.feature_id.trim().is_empty()||self.boundary!=PRECLINICAL_BOUNDARY||self.artifact.get("boundary").and_then(|v|v.as_str())!=Some(PRECLINICAL_BOUNDARY)||self.artifact.get("content_type").and_then(|v|v.as_str())!=Some(CONTENT_TYPE)||!self.raw_data_local||!self.aggregate_only||self.workflow_id.trim().is_empty()||self.stage_order.is_empty()||self.stage_order.len()!=self.completed_stage_order.len()+self.pending_stage_order.len()||self.budget_units==0||self.consumed_units>self.budget_units||self.checkpoint_seq==0||self.effect_receipts.is_empty()||![&self.replay_identity,&self.workflow_digest].into_iter().all(digest){return Err(ContextWorkflowError::Receipt("context workflow identity, stages, budget, locality, or effects are incomplete".into()));}for v in [&self.stage_order,&self.completed_stage_order,&self.pending_stage_order,&self.compensation_order,&self.effect_receipts]{if !ordered(v){return Err(ContextWorkflowError::Receipt("context workflow ordering is not canonical".into()));}}let ids=self.stage_order.iter().cloned().collect::<BTreeSet<_>>();let parts=self.completed_stage_order.iter().chain(&self.pending_stage_order).cloned().collect::<Vec<_>>();if ids.len()!=self.stage_order.len()||parts.len()!=ids.len()||parts.iter().cloned().collect::<BTreeSet<_>>()!=ids{return Err(ContextWorkflowError::Receipt("context workflow stages do not partition".into()));}if self.copilot.validate().is_err(){return Err(ContextWorkflowError::Receipt("nested context copilot receipt is invalid".into()));}if self.artifact.get("content_hash").and_then(|v|v.as_str())!=Some(self.workflow_digest.as_str()){return Err(ContextWorkflowError::Receipt("context workflow artifact digest is inconsistent".into()));}if self.effect_receipts.iter().any(|e|e!="block:unsafe-release"&&!e.starts_with("schedule:worldgen-context-workflow:")){return Err(ContextWorkflowError::Receipt("context workflow effect is outside scheduling gate".into()));}Ok(())}pub fn digest(&self)->Result<ContentHash,ContextWorkflowError>{self.validate()?;serde_json::to_value(self).map_err(|e|ContextWorkflowError::Artifact(e.to_string())).and_then(|v|ContentHash::of_value(&v).map_err(|e|ContextWorkflowError::Artifact(e.to_string())))}}
pub fn manifest(feature_id:&str,version:&str,input_schema:&str,scale:&str,autonomy:&str)->serde_json::Value{json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"capability_id":feature_id,"version":version,"owner_crate":"worldgen","consumers":["preclinical neuroscientist","context compiler","workflow operator","downstream crate consumer"],"behavior":format!("orchestrate a resumable context-compilation workflow for {scale} with checkpoints and compensation"),"value":"makes typed context assembly restartable, budgeted, and replayable without hidden effects","input_schema":input_schema,"output_schema":"CompiledResearchContext6@1","effects":["schedule:worldgen-context-workflow","block:unsafe-release"],"permissions":["schedule:bounded-context-workflow"],"determinism":"byte_stable","autonomy_tier":autonomy,"boundary":PRECLINICAL_BOUNDARY})}
pub fn schedule(request:&ContextWorkflowRequest,feature_id:&str,version:&str,scale:&str,require_approval:bool,require_federation:bool)->Result<ContextWorkflowReceipt,ContextWorkflowError>{if request.workflow_id.trim().is_empty()||request.stage_order.is_empty()||request.budget_units==0||request.checkpoint_seq==0||!request.compensation_enabled||!digest(&request.replay_identity)||request.copilot.context_request.replay_identity!=request.replay_identity{return Err(ContextWorkflowError::Invalid("context workflow identity, stages, checkpoint, budget, compensation, or replay is invalid".into()));}let stages=sorted(&request.stage_order);if stages.len()!=request.stage_order.len()||request.completed_stage_order.iter().any(|s|!stages.contains(s)){return Err(ContextWorkflowError::Invalid("context workflow stages must be unique and declared".into()));}let copilot=context_copilot_support::run(&request.copilot,feature_id,version,scale,require_approval,require_federation).map_err(|e|ContextWorkflowError::Invalid(e.to_string()))?;let completed=request.completed_stage_order.iter().cloned().collect::<BTreeSet<_>>();let pending=stages.iter().filter(|s|!completed.contains(*s)).cloned().collect::<Vec<_>>();let consumed=(request.copilot.action_order.len() as u64).min(request.budget_units);let mut compensation=Vec::new();if copilot.disposition=="blocked"||request.copilot.action_order.len() as u64>request.budget_units{compensation.push(format!("workflow:{}:retain-partial-context",request.workflow_id));}let disposition=if copilot.disposition=="blocked"||!compensation.is_empty(){"blocked"}else if pending.is_empty(){"qualified"}else{"partial"};let effects=if disposition=="qualified"{vec![format!("schedule:worldgen-context-workflow:{}",request.workflow_id)]}else{vec!["block:unsafe-release".into()]};let payload=json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"contract_version":version,"feature_id":feature_id,"workflow_id":request.workflow_id,"disposition":disposition,"stage_order":stages,"completed_stage_order":completed,"pending_stage_order":pending,"compensation_order":compensation,"checkpoint_seq":request.checkpoint_seq,"budget_units":request.budget_units,"consumed_units":consumed,"replay_identity":request.replay_identity,"copilot":copilot.clone(),"effect_receipts":effects,"raw_data_local":true,"aggregate_only":true,"boundary":PRECLINICAL_BOUNDARY});let workflow_digest=ContentHash::of_value(&payload).map_err(|e|ContextWorkflowError::Artifact(e.to_string()))?;let receipt=ContextWorkflowReceipt{schema_version:RESEARCH_CONTRACT_SCHEMA_VERSION.into(),contract_version:version.into(),feature_id:feature_id.into(),workflow_id:request.workflow_id.clone(),disposition:disposition.into(),stage_order:sorted(&request.stage_order),completed_stage_order:sorted(&request.completed_stage_order),pending_stage_order:pending,compensation_order:sorted(&payload["compensation_order"].as_array().unwrap().iter().map(|v|v.as_str().unwrap().to_owned()).collect::<Vec<_>>()),checkpoint_seq:request.checkpoint_seq,budget_units:request.budget_units,consumed_units:consumed,replay_identity:request.replay_identity.clone(),copilot,workflow_digest:workflow_digest.clone(),artifact:json!({"artifact_id":format!("worldgen-context-workflow:{}",request.workflow_id),"content_type":CONTENT_TYPE,"content_hash":workflow_digest,"boundary":PRECLINICAL_BOUNDARY}),effect_receipts:sorted(&effects),raw_data_local:true,aggregate_only:true,boundary:PRECLINICAL_BOUNDARY.into()};receipt.validate()?;Ok(receipt)}
#[cfg(test)]mod tests{use super::*;use crate::context_copilot_support::ContextCopilotRequest;use crate::context_compilation_support::{ContextFact,ContextCompilationRequest};use bioprism_foundation::EvidenceState;fn h(v:&str)->ContentHash{ContentHash::of_bytes(v.as_bytes())}fn request()->ContextWorkflowRequest{let replay=h("replay");let fact=ContextFact{fact_id:"fact:a".into(),statement:"supported".into(),support_milli:900,state:EvidenceState::Supported,evidence_digest:h("e"),provenance_digest:h("p"),artifact_digest:h("a"),replay_identity:replay.clone(),negative_result:false,raw_data_local:true,boundary:PRECLINICAL_BOUNDARY.into()};let context=ContextCompilationRequest{request_id:"workflow:req".into(),objective:"compile".into(),scope:"study:one".into(),required_fact_order:vec!["fact:a".into()],minimum_support_milli:500,facts:vec![fact],replay_identity:replay.clone(),policy_allow:true,protected_closure:true,federation_approved:true,raw_data_local:true,aggregate_only:true,boundary:PRECLINICAL_BOUNDARY.into()};ContextWorkflowRequest{workflow_id:"workflow:a".into(),copilot:ContextCopilotRequest{context_request:context,action_order:vec!["read:local-context".into()],action_budget:2,dry_run:false,signed_approval:true,federation_approved:true,boundary:PRECLINICAL_BOUNDARY.into()},stage_order:vec!["compile".into(),"audit".into()],completed_stage_order:vec!["compile".into(),"audit".into()],checkpoint_seq:1,budget_units:4,compensation_enabled:true,replay_identity:replay}}#[test]fn completed_workflow_schedules_effect(){let r=schedule(&request(),"AFA-worldgen-P03-F13","worldgen-local-context-compilation-workflow/1.0","local single-study",false,false).unwrap();assert_eq!(r.disposition,"qualified");assert!(r.effect_receipts[0].starts_with("schedule:worldgen-context-workflow:"));assert!(r.digest().is_ok())}#[test]fn pending_is_partial(){let mut q=request();q.completed_stage_order=vec!["compile".into()];let r=schedule(&q,"AFA-worldgen-P03-F13","worldgen-local-context-compilation-workflow/1.0","local single-study",false,false).unwrap();assert_eq!(r.disposition,"partial");assert_eq!(r.pending_stage_order,vec!["audit"])}#[test]fn approval_failure_blocks(){let mut q=request();q.copilot.signed_approval=false;let r=schedule(&q,"AFA-worldgen-P03-F14","worldgen-multimodal-context-compilation-workflow/1.0","multimodal multi-study",true,false).unwrap();assert_eq!(r.disposition,"blocked");assert_eq!(r.effect_receipts,vec!["block:unsafe-release"])} }
